from core2 import Q,R,load,dump,METHODS
import csv,json,datetime,hashlib,collections
def main():
 designs=load(Q/'rtl/design_manifest.json');ppa=load(Q/'results/hardware/ppa.json');by={r['top']:r for r in ppa};assert len(ppa)==sum(not e['duplicate_of']for e in designs);rows=[];groups=[];scans=[]
 for e in designs:
  r=by[e['duplicate_of']or e['top']];raw=list(csv.DictReader((Q/f'results/{e["case"]}_replay.csv').open()));mi=METHODS.index(e['method']);f=next(x for x in raw if int(x['method'])==mi and x['stage']=='final');assert int(f['WCE'])<=e['budget']
  rows.append(dict(case=e['case'],method=e['method'],LUT=r['LUT'],WCE=e['WCE'],budget=e['budget'],merges=len(e['choices']),FF=r['FF'],CARRY4=r['CARRY4'],DSP=r['DSP'],clock_ns=r['clock_ns'],WNS_ns=r['WNS_ns'],WHS_ns=r['WHS_ns'],FF_period_ns=r['FF_period_ns'],pass_registered_clock=r['pass_registered_clock'],MAE_at_lowbits_zero=float(f['MAE_at_lowbits_zero']),error_count_at_lowbits_zero=int(f['error_count_at_lowbits_zero']),inputs=int(f['inputs'])))
 for c in load(Q/'configs/plan.json')['cases']:
  name=c['name'];rr={r['method']:r for r in rows if r['case']==name};pairs=load(Q/f'graphs/{name}_pairs.json');records=load(Q/f'results/{name}_methods.json');scans+=list(csv.DictReader((Q/f'results/{name}_replay.csv').open()));simple=sum(len(p['a_ins'])<=5 and len(p['b_ins'])<=5 and len(p['support'])<=5 for p in pairs)
  groups.append(dict(case=name,LUT={m:r['LUT']for m,r in rr.items()},gain_vs_seed_pct=100*(rr['seed']['LUT']-rr['joint']['LUT'])/rr['seed']['LUT'],gain_vs_serial_pct=100*(rr['serial']['LUT']-rr['joint']['LUT'])/rr['serial']['LUT'],candidate_count=len(pairs),already_exact_five_input_packable_pairs=simple,joint_only_feasible_pairs=sum(r['methods']['joint']is not None and r['methods']['serial']is None for r in records),timing_pass={m:r['pass_registered_clock']for m,r in rr.items()}))
 data=dict(round=2,status='COMPLETE_AWAIT_SCORE',completed=datetime.datetime.now().astimezone().isoformat(),rows=rows,cases=groups,full_domain_scans=len(scans),effective_inputs_evaluated=sum(int(r['inputs'])for r in scans),unique_physical_jobs=len(ppa),hdl=load(Q/'state/rtl_validation.json'),scope='fixed four seeds, two baselines and one innovation, sampled proposals followed by full-domain admission; sqrt common 25ns, multipliers common 10ns',limits=['serial is a specified local reference, not complete author-flow reproduction','candidate pool includes exact-packable LUT4/LUT5 pairs; their gains alone do not establish newly created approximate sharing','sampled multiplier contexts are not proofs; only admitted full-domain results support hard WCE','all physical designs have one default placement and route; no placement robustness claim','baseline seed import uses exact LUT6_2 decomposition; seed scalar lineage checks and vendor simulation must pass'])
 dump(Q/'state/analysis.json',data)
 with(Q/'reports/RESULTS.csv').open('w',newline='')as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 hashes={p.relative_to(Q).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()for sub in ['tools','configs','src','rtl','graphs','results']for p in(Q/sub).rglob('*')if p.is_file()and p.suffix in['.py','.tcl','.json','.cpp','.v','.sv','.xdc','.csv','.hex','.log','.rpt','.stderr']};dump(Q/'state/evidence_hashes.json',hashes);print(json.dumps(groups,indent=2));print('full scans',len(scans))
if __name__=='__main__':main()
